mapper.select:
select s.seal_id, s.user_id, s.seal_name, s.seal_image_url, s.material_urls, s.review_status, s.seal_status, s.reject_reason, s.reviewer_id, s.review_time, s.create_time, u.nick_name, u.user_name from sys_copyright_seal s left join sys_user u on u.user_id = s.user_id where s.is_deleted = 0
and s.review_status = #{reviewStatus}
and s.seal_status = #{sealStatus}
and (s.seal_name like concat('%', #{keyword}, '%') or u.nick_name like concat('%', #{keyword}, '%') or u.user_name like concat('%', #{keyword}, '%'))
order by s.create_time desc, s.seal_id desc
